def wrap(text, width):
    if width < 1:
        raise ValueError
    # split into words
    words = text.split()
    if not words:
        return []
    lines = []
    cur = ''
    i = 0
    while i < len(words):
        w = words[i]
        # handle long word splitting
        if len(w) > width:
            # split w into chunks of width
            start = 0
            while start < len(w):
                chunk = w[start:start+width]
                start += width
                # place chunk like a word
                if not cur:
                    cur = chunk
                elif len(cur) + 1 + len(chunk) <= width:
                    cur += ' ' + chunk
                else:
                    lines.append(cur)
                    cur = chunk
            i += 1
            continue
        # normal word
        if not cur:
            cur = w
        elif len(cur) + 1 + len(w) <= width:
            cur += ' ' + w
        else:
            lines.append(cur)
            cur = w
        i += 1
    if cur:
        lines.append(cur)
    return lines

